CREATE TABLE "SYS_CODE" (
    "Id" NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "CODE_TYPE" NVARCHAR2(100) NOT NULL,
    "CODE" NVARCHAR2(100) NOT NULL,
    "NAME_AR" NVARCHAR2(500) NOT NULL,
    "NAME_EN" NVARCHAR2(500) NOT NULL,
    "DISPLAY_ORDER" NUMBER(10),
    "IS_ACTIVE" NUMBER(10) NOT NULL,
    "CODE_MGR" NUMBER(10),
    "CODE_MNR" NUMBER(10),
    "CODE_LANG" NUMBER(10),
    "CODE_DESC" NVARCHAR2(1000),
    "CREATION_USER" NVARCHAR2(100) NOT NULL,
    "CREATION_DATE" TIMESTAMP(7),
    "UPDATE_USER" NVARCHAR2(100),
    "UPDATE_DATE" TIMESTAMP(7),
    CONSTRAINT "PK_SYS_CODE" PRIMARY KEY ("Id")
)
/

CREATE UNIQUE INDEX "IX_SYS_CODE_CODE_TYPE_CODE" ON "SYS_CODE" ("CODE_TYPE", "CODE")
/

